// Generates lib/worker-bundle.js — every lib/*.js concatenated into one file
// that a QML WorkerScript can load.
//
// Why this exists: WorkerScript runs on its own thread with its own JS engine,
// and that engine does not honour `.import` (the namespaces come back
// undefined, and on a deep import chain it segfaults outright). XMLHttpRequest
// can't read file:// URLs unless QML_XHR_ALLOW_FILE_READ is set globally,
// which would weaken every other QML app in the shell. Qt.include exists but
// dumps everything into one flat scope, where json/yaml/cron/url/time/color
// would each clobber the previous module's `parse`.
//
// So: each module becomes an IIFE assigned to its namespace name. Because the
// IIFEs nest in one shared outer scope in dependency order, a module body that
// says `Bytes.toUtf8(...)` resolves to the `var Bytes` declared above it —
// exactly the shape `.import "bytes.js" as Bytes` would have produced — while
// each module's internals stay private inside its own function scope.
//
// Run after touching anything in lib/:
//   node tools/build-worker-bundle.mjs
//
// tests/run.mjs fails if the committed bundle is stale, so a forgotten rebuild
// is caught rather than shipped.

import fs from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..")
const LIB_DIR = path.join(ROOT, "lib")
const OUTPUT = path.join(LIB_DIR, "worker-bundle.js")

// Files in lib/ that are not libraries: the generated bundle itself, and the
// WorkerScript entry point that loads it. Bundling either produces a file that
// includes itself.
const NOT_A_LIBRARY = ["worker-bundle.js", "worker.js"]

const IMPORT_RE = /^\s*\.import\s+"([^"]+)"\s+as\s+([A-Za-z_$][\w$]*)\s*$/gm
const PRAGMA_RE = /^\s*\.pragma\s+library\s*$/gm

// Namespace name a module is imported under, derived from how its siblings
// import it (bytes.js -> Bytes). Falls back to a capitalised file name for a
// module nothing imports yet.
function namespaceOf(file, byFile) {
  return byFile.get(file)
    || file.replace(/\.js$/, "").replace(/(^|[-_])(\w)/g, (_, __, c) => c.toUpperCase())
}

function readModules() {
  const files = fs.readdirSync(LIB_DIR)
    .filter(f => f.endsWith(".js") && !NOT_A_LIBRARY.includes(f))
    .sort()

  const modules = new Map()
  const namespaceByFile = new Map()

  for (const file of files) {
    const source = fs.readFileSync(path.join(LIB_DIR, file), "utf8")
    const dependencies = []
    for (const match of source.matchAll(IMPORT_RE)) {
      dependencies.push(match[1])
      namespaceByFile.set(match[1], match[2])
    }
    modules.set(file, { file, source, dependencies })
  }

  for (const module of modules.values()) module.namespace = null
  for (const module of modules.values())
    module.namespace = namespaceOf(module.file, namespaceByFile)

  return modules
}

// Depth-first topological sort so a module is always emitted after everything
// it imports.
function orderModules(modules) {
  const ordered = []
  const state = new Map()

  function visit(file, trail) {
    if (state.get(file) === "done") return
    if (state.get(file) === "visiting")
      throw new Error("import cycle: " + trail.concat(file).join(" -> "))
    const module = modules.get(file)
    if (!module) throw new Error("imported file not found in lib/: " + file)

    state.set(file, "visiting")
    for (const dependency of module.dependencies) visit(dependency, trail.concat(file))
    state.set(file, "done")
    ordered.push(module)
  }

  for (const file of modules.keys()) visit(file, [])
  return ordered
}

// Top-level declarations become the module's exports. Anchoring to column zero
// is what distinguishes a module-level declaration from a nested one, and every
// lib in this plugin is written that way.
function exportsOf(source) {
  const names = []
  for (const match of source.matchAll(/^(?:function|var)\s+([A-Za-z_$][\w$]*)/gm))
    if (!names.includes(match[1])) names.push(match[1])
  return names
}

function build() {
  const modules = readModules()
  const ordered = orderModules(modules)
  const chunks = []

  chunks.push("// GENERATED by tools/build-worker-bundle.mjs — do not edit.")
  chunks.push("// Source of truth is the individual files in lib/; run the generator after")
  chunks.push("// changing any of them. tests/run.mjs fails if this file is stale.")
  chunks.push("")

  for (const module of ordered) {
    const body = module.source.replace(PRAGMA_RE, "").replace(IMPORT_RE, "")
    const names = exportsOf(body)
    chunks.push(`// ---------------------------------------------------------------- ${module.file}`)
    chunks.push(`var ${module.namespace} = (function () {`)
    chunks.push(body.replace(/^\s+$/gm, "").replace(/\n{3,}/g, "\n\n").trim())
    chunks.push("")
    chunks.push("  return {")
    chunks.push(names.map(n => `    ${n}: ${n}`).join(",\n"))
    chunks.push("  }")
    chunks.push("})()")
    chunks.push("")
  }

  return chunks.join("\n")
}

export function bundleSource() { return build() }

// Executed directly (rather than imported by the test suite): write the file.
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const source = build()
  fs.writeFileSync(OUTPUT, source)
  const moduleCount = orderModules(readModules()).length
  console.log(`wrote ${path.relative(ROOT, OUTPUT)} — ${moduleCount} modules, ${source.length} bytes`)
}
